def _handle_persistence_integrity_history_page(self) -> None:
    # keep_blank_values so an explicit ``after=``/``limit=`` is an empty
    # (hence malformed, 400) value rather than silently defaulting.
    query = parse_qs(urlsplit(self.path).query,
                     keep_blank_values=True)
    after = self._decimal_nonneg_param(query, "after", default=0)
    if after is None:
        return  # a 400 response was already sent
    limit = self._decimal_nonneg_param(query, "limit", default=100,
                                       minimum=1, maximum=100)
    if limit is None:
        return  # a 400 response was already sent
    try:
        body = self.service.persistence_integrity_history_page(
            after, limit)
    except ServiceError as error:
        self._send_json(error.status_code, error.to_body())
        return
    self._send_json(200, body)

def _handle_register(self) -> None:
    payload = self._read_json_request()
    if payload is _BAD_REQUEST:
        return
    try:
        body = self.service.register(payload)
    except ServiceError as error:
        self._send_json(error.status_code, error.to_body())
        return
    self._send_json(201, body)

def _handle_show(self, device_id: str) -> None:
    try:
        body = self.service.get_device(device_id)
    except ServiceError as error:
        self._send_json(error.status_code, error.to_body())
        return
    self._send_json(200, body)

def _handle_key_events(self, device_id: str) -> None:
    query = parse_qs(urlsplit(self.path).query)
    after = self._int_param(query, "after", default=0, minimum=0)
    if after is None:
        return  # a 400 response was already sent
    limit = self._int_param(query, "limit", default=100,
                            minimum=1, maximum=100)
    if limit is None:
        return  # a 400 response was already sent
    try:
        body = self.service.list_key_events(device_id, after, limit)
    except ServiceError as error:
        self._send_json(error.status_code, error.to_body())
        return
    self._send_json(200, body)

